import {colors,puzzleSVG} from './puzzle.js';
const $=s=>document.querySelector(s),app=$('#app');
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const demoImage='data:image/svg+xml;base64,'+btoa(`<svg xmlns="http://www.w3.org/2000/svg" width="1000" height="1000" viewBox="0 0 300 300"><rect width="300" height="300" fill="#b7a3e2"/><circle cx="150" cy="154" r="118" fill="#d2c2ec"/><path d="M67 76h67c-7-9-10-16-10-23 0-27 50-27 50 0 0 8-5 17-11 23h70v65c9-7 15-10 23-10 28 0 28 50 0 50-8 0-15-4-23-10v65h-68c7-8 11-16 11-24 0-28-50-28-50 0 0 8 4 16 10 24H67v-66c9 6 16 10 24 10 27 0 27-50 0-50-8 0-15 4-24 10Z" fill="#fac85b" stroke="#1b1c18" stroke-width="7" stroke-linejoin="round"/><ellipse cx="126" cy="128" rx="8" ry="12" fill="#1b1c18"/><ellipse cx="180" cy="128" rx="8" ry="12" fill="#1b1c18"/><circle cx="128" cy="124" r="3" fill="white"/><circle cx="182" cy="124" r="3" fill="white"/><path d="M138 155q15 18 29 0" fill="none" stroke="#1b1c18" stroke-width="6" stroke-linecap="round"/><ellipse cx="111" cy="149" rx="11" ry="7" fill="#f596a4"/><ellipse cx="195" cy="149" rx="11" ry="7" fill="#f596a4"/><path d="M26 21l4 7 8 1-6 5 2 8-8-4-7 4 2-8-6-5 8-1Z" fill="#fac85b"/><circle cx="266" cy="262" r="7" fill="#a9d49a"/></svg>`);
const behaviors=[
 {id:'buyback',code:'FN',name:'Buy back tokens',desc:'Turn creator fees into buying power.',category:'Money',color:colors[0],param:'SOL per buyback',value:'0.01',effect:'buy back tokens'},
 {id:'burn',code:'FN',name:'Burn tokens',desc:'Take tokens out of circulation.',category:'Money',color:colors[3],param:'Tokens per burn',value:'1000',effect:'burn tokens'},
 {id:'airdrop',code:'FN',name:'Reward holders',desc:'Give a little back to your community.',category:'Money',color:colors[1],param:'SOL to distribute',value:'0.01',effect:'airdrop SOL to holders'},
 {id:'agent',code:'AG',name:'Create a character',desc:'A new personality for every milestone.',category:'Agents',color:colors[2],param:'Character species',value:'puzzle pal',effect:'create a character'},
 {id:'post',code:'OP',name:'Post to your feed',desc:'Keep your community in the loop.',category:'Social',color:colors[4],param:'Post message',value:'Another piece of the puzzle!',effect:'post to your feed'},
 {id:'meme',code:'MD',name:'Make a meme',desc:'Give every milestone a little personality.',category:'Media',color:colors[3],param:'Meme prompt',value:'a happy puzzle piece on the moon',effect:'generate a meme'},
 {id:'bounty',code:'BT',name:'Create a bounty',desc:'Reward your community for making things.',category:'Bounties',color:colors[0],param:'Bounty challenge',value:'Create the best puzzle meme',effect:'open a bounty'},
 {id:'webhook',code:'WB',name:'Call a webhook',desc:'Connect the puzzle to your own app.',category:'Web',color:colors[4],param:'Webhook HTTPS URL',value:'',effect:'call your webhook'},
 {id:'counter',code:'ST',name:'Keep a counter',desc:'Remember every step along the way.',category:'State',color:colors[1],param:'Counter name',value:'pieces_connected',effect:'increment a counter'},
 {id:'condition',code:'LG',name:'Add a condition',desc:'Only continue when your rule is met.',category:'Logic',color:colors[2],param:'Minimum event SOL',value:'0.01',effect:'check a condition'},
 {id:'write',code:'AI',name:'Write a message',desc:'Give your next update a little imagination.',category:'AI',color:colors[2],param:'Writing prompt',value:'Write an upbeat update about our puzzle community',effect:'write a message'},
 {id:'world',code:'WD',name:'Build your world',desc:'Give your community a place to play.',category:'Worlds',color:colors[1],param:'World entity name',value:'puzzle garden',effect:'create a world entity'},
 {id:'random',code:'DT',name:'Pick a random idea',desc:'Let a little chance choose your next move.',category:'Data',color:colors[0],param:'Choices, separated by commas',value:'celebrate,create,connect',effect:'choose a random value'}
];
const modules=[['EV','Events','Every good puzzle starts with something.','trades · holders · timers',colors[0]],['LG','Logic','Choose when the next piece fits.','if · repeat · chance',colors[2]],['AI','AI','Give your coin a little imagination.','write · decide · create',colors[2]],['AG','Agents','Characters with a life of their own.','personality · memory',colors[1]],['MD','Media','Make something worth sharing.','images · memes · avatars',colors[3]],['WB','Web','Connect to the world outside.','APIs · webhooks',colors[4]],['FN','Money','Give every fee a purpose.','buy back · burn · reward',colors[0]],['WD','Worlds','A home for all your pieces.','feed · rooms · entities',colors[1]],['BT','Bounties','Let your community play a part.','challenges · rewards',colors[3]],['ST','State','Keep track of the bigger picture.','variables · counters',colors[4]],['DT','Data','Find the pieces you need.','lists · numbers · random',colors[0]],['OP','Social','Keep everyone connected.','posts · notifications',colors[3]]];
const templates=[{id:'community',name:'The Community Puzzle',ticker:'TOGETHER',desc:'A little buyback. A holder reward. A reason to stay connected.',count:3,items:['buyback','airdrop','post'],color:colors[1],emoji:'🫶'},{id:'meme',name:'The Meme Machine',ticker:'PIECE',desc:'New characters, new memes, and a feed that keeps the story going.',count:4,items:['agent','meme','post','counter'],color:colors[2],emoji:'✦'},{id:'deflation',name:'The Missing Piece',ticker:'MISSING',desc:'Buy back, burn, and celebrate every community milestone.',count:5,items:['condition','buyback','burn','post','counter'],color:colors[0],emoji:'🔥'}];
const blank=()=>({id:crypto.randomUUID(),count:4,image:'',isDemo:false,items:[],name:'',symbol:'',description:'',twitter:'',telegram:'',website:'',trigger:'buy',threshold:'0.01',counter:0,metadataURI:'',rpc:'https://api.mainnet-beta.solana.com',imageURI:''});
let state=blank(),drafts=[],wallet=null,step=1,launchBusy=false,submitted=null;
try{const saved=JSON.parse(localStorage.getItem('puzzled-current'));if(saved&&[3,4,5].includes(saved.count)){state={...state,...saved};state.items=state.items.filter(i=>behaviors.some(b=>b.id===i.id)).slice(0,state.count);}drafts=JSON.parse(localStorage.getItem('puzzled-drafts'))||[];}catch{}
submitted=state.pendingLaunch||(state.mint?{mint:state.mint,signature:state.signature}:null);
function save(){try{localStorage.setItem('puzzled-current',JSON.stringify(state));const at=drafts.findIndex(d=>d.id===state.id);const entry={...state,updated:Date.now()};if(at<0)drafts.unshift(entry);else drafts[at]=entry;drafts=drafts.slice(0,8);localStorage.setItem('puzzled-drafts',JSON.stringify(drafts));$('.save-indicator')?.replaceChildren(document.createTextNode('✓ Saved on this device'));}catch{toast('Device storage is full. Export your project to keep a copy.');}}
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000);}
function dialog(content){$('#dialog-content').innerHTML=content;$('#dialog').showModal();}
function closeDialog(){$('#dialog').close();}
function footer(){return `<footer><div class="footer-about"><a href="#/" class="brand"><img src="mascot.svg" alt="">PUZZLED</a><p>A launchpad where every piece has a purpose. Assemble your PFP, connect your ideas, and make something that fits.</p></div><div><h4>PLATFORM</h4><div class="links"><a href="#/build">Builder</a><a href="#/modules">Piece library</a><a href="#/examples">Examples</a><a href="#/coins">My coins</a></div></div><div><h4>LEARN</h4><div class="links"><a href="#/docs">How it works</a><a href="#/docs?section=launch">Launching</a><a href="#/docs?section=simulation">Simulation</a><a href="#/docs?section=faq">FAQ</a></div></div><div><h4>CONNECTED</h4><div class="links"><a href="https://pump.fun" target="_blank" rel="noopener">pump.fun ↗</a><a href="https://solana.com" target="_blank" rel="noopener">Solana ↗</a><a href="#/docs?section=privacy">Privacy</a><a href="#/docs?section=launch">Launch requirements</a></div></div><div class="copyright"><span>© 2026 PUZZLED. Every piece has a purpose.</span><span>BUILT TO FIT. 🧩</span></div></footer>`;}
function ticker(){return `<div class="ticker"><b class="ticker-label">THE POSSIBILITIES</b><div class="ticker-track">${Array(2).fill('<span>Reward your holders</span><span>Bring a character to life</span><span>Make a meme</span><span>Buy back & burn</span><span>Connect your community</span><span>Launch on pump.fun</span>').join('')}</div></div>`;}
function floating(color,code,text,cls){return `<div class="float-piece ${cls}" aria-hidden="true"><svg viewBox="0 0 180 85"><path d="M12 18H58c-8-19 24-19 16 0H164v23c-18-9-18 22 0 13v20H109c8-19-24-19-16 0H12V52c18 9 18-22 0-13Z" fill="${color}" stroke="#1b1c18" stroke-width="2.3" stroke-linejoin="round"/><rect x="22" y="36" width="20" height="18" rx="4" fill="#ffffff9a" stroke="#1b1c18"/><text x="32" y="48" text-anchor="middle">${code}</text><text x="50" y="48">${text}</text></svg></div>`;}
function moduleCards(list=modules){return list.map(m=>`<a href="#/build?category=${m[0]}" class="piece-card module-card" style="--card:${m[4]}"><span class="category-icon">${m[0]}</span><h3>${m[1]}</h3><p>${m[2]}</p><div class="meta">${m[3]}</div></a>`).join('');}
function exampleCards(list=templates){return list.map(t=>`<article class="piece-card" style="--card:#fff"><div class="example-art" style="--card:${t.color}">${t.id==='meme'?puzzleSVG({count:t.count,image:demoImage,all:true}):`<span>${t.emoji}</span>`}</div><div class="example-info"><h3>${t.name}</h3><small>$${t.ticker}</small></div><p>${t.desc}</p><div class="mini-pieces">${t.items.map(id=>{const b=behaviors.find(b=>b.id===id);return `<span class="category-icon" style="--card:${b.color}">${b.code}</span>`;}).join('')}</div><button class="text-button" data-template="${t.id}">Try this ${t.count}-piece puzzle →</button></article>`).join('');}
function home(){return `${ticker()}<main><section class="hero"><div class="announcement"><b>● MEET PUZZLED</b><span>A new way to piece your coin together.</span><span>↗</span></div>${floating(colors[0],'EV','when someone buys','float-a')}${floating(colors[1],'FN','reward your holders','float-b')}${floating(colors[2],'AG','create a character','float-c')}${floating(colors[3],'MD','make a meme','float-d')}<img class="hero-mascot" src="mascot.svg" alt="Pip, the smiling PUZZLED puzzle piece"><div class="eyebrow"><i class="dot"></i>No code. Just pieces.</div><h1>MAKE YOUR COIN<br><span class="outline">COME TOGETHER.</span></h1><p>One PFP. A few good ideas. Endless possibilities.<br>Piece together what your coin does. No code required.</p><div class="actions"><a class="button yellow" href="#/build">Open Builder <span>→</span></a><a class="plain-link" href="#/describe">Describe an idea ↗</a></div><div class="hero-tags"><span>Launch on pump.fun</span><span>3, 4 or 5 pieces</span><span>Your PFP. Your puzzle.</span></div></section><div class="stats"><div class="stats-label"><i class="dot"></i> SMALL PIECES. BIG IDEAS.<small>Everything you need to get started.</small></div><div class="stat"><b>3–5</b><small>Pieces per coin</small></div><div class="stat"><b>12</b><small>Piece categories</small></div><div class="stat"><b>∞</b><small>Possibilities</small></div><div class="stat"><b>0</b><small>Code required</small></div></div><section class="section how"><div><span class="small-tag">YOUR IMAGE. YOUR IDEAS.</span><h2>A bigger picture.<br>One piece at a time.</h2><p class="text-lead">Upload your PFP. Break it into 3, 4, or 5 puzzle pieces. Give each piece a purpose and watch your image come back together.</p><p class="help">The last piece clicks into place. Your coin is ready for its next chapter.</p><a class="plain-link" href="#/build">Piece yours together →</a></div><div class="puzzle-surface"><div class="puzzle-demo">${puzzleSVG({count:4,image:demoImage,selected:3,scatter:true})}</div></div></section><section class="section" style="padding-top:20px"><div class="section-head"><div><span class="small-tag">A FEW PIECES. A WHOLE NEW COIN.</span><h2>Find your fit.</h2></div><a class="plain-link" href="#/docs">How it works ↗</a></div><div class="steps-grid"><article class="piece-card" style="--card:#fff0c6"><span class="step-number">01</span><h3>Break it up.</h3><p>Start with your PFP and choose 3, 4, or 5 pieces. Your image becomes your canvas.</p></article><article class="piece-card" style="--card:#e4efd9"><span class="step-number">02</span><h3>Give each piece a job.</h3><p>Rewards, characters, memes, and more. Every selection connects another piece.</p></article><article class="piece-card" style="--card:#eae0f7"><span class="step-number">03</span><h3>Complete. Then create.</h3><p>Once your PFP is whole, add your coin details and prepare your pump.fun launch.</p></article></div></section><div class="subtle-section"><section class="section"><div class="section-head"><div><span class="small-tag">A PIECE FOR EVERY IDEA</span><h2>Anything can be a puzzle piece.</h2></div><a class="plain-link" href="#/modules">Explore all pieces →</a></div><div class="modules-grid">${moduleCards(modules.slice(0,8))}</div></section></div><section class="section" id="describe"><span class="small-tag">MEET PIP, YOUR PUZZLE PAL</span><h2>Or start with an idea.</h2><p>Tell Pip what you have in mind. Find a starting puzzle to make your own.</p><form id="idea-form" class="describe-box"><img src="mascot.svg" alt="Pip"><textarea aria-label="Describe your coin idea" placeholder="When someone buys my coin, reward holders and make a meme…"></textarea><button class="button yellow" type="submit">Find my pieces ↑</button></form><div class="suggestions"><span class="help">Try:</span><button class="chip" data-idea="Reward holders and buy back tokens whenever someone buys">reward holders on every buy</button><button class="chip" data-idea="Create a character and make a meme and post to the feed">make a meme for every buyer</button><button class="chip" data-idea="Burn tokens and keep a counter whenever creator fees arrive">buy back and burn with fees</button></div></section><section class="section" style="padding-top:20px"><div class="section-head"><div><span class="small-tag">A LITTLE INSPIRATION</span><h2>Good ideas fit together.</h2></div><a class="plain-link" href="#/examples">All examples →</a></div><div class="examples-grid">${exampleCards()}</div></section><section class="cta"><span class="small-tag">THE NEXT PIECE IS YOURS.</span><h2>WHAT WILL YOU<br>PIECE TOGETHER?</h2><a class="button" href="#/build">Start building <span>→</span></a></section></main>${footer()}`;}
function steps(){return `<div class="build-steps">${['Piece it together','Coin details','Review & launch'].map((s,i)=>`<div class="build-step ${step===i+1?'current':step>i+1?'done':''}"><b>${step>i+1?'✓':i+1}</b>${s}</div>`).join('')}</div>`;}
function builderTop(){return `<div class="builder-top"><div class="builder-title"><strong>Your puzzle workspace</strong><small>Every piece has a purpose.</small></div><div><span class="save-indicator">${state.image?'✓ Saved on this device':'Your next big idea starts here'}</span> <button class="text-button" data-action="export">Export</button></div></div>${steps()}`;}
function builder(){if(step===2)return details();if(step===3)return review();const completed=state.items.length===state.count&&!!state.image;return `<main>${builderTop()}<div class="builder-shell"><aside class="builder-sidebar"><h3>Start with your PFP.</h3><p class="help">Your image is the puzzle. Every selected behavior brings one piece back.</p><button class="upload-zone" data-action="upload">${state.image?`<img src="${state.image}" alt="Uploaded PFP">`:'<span style="font-size:30px">↥</span>'}<strong>${state.image?'Change your PFP':'Drop your PFP here'}</strong><small>or click to upload · PNG, JPG, WebP<br>Up to 15 MB · center-cropped to a square</small></button><input id="file-input" type="file" accept="image/png,image/jpeg,image/webp" hidden><label class="label">How many pieces?</label><div class="count-picker" aria-label="Puzzle piece count">${[3,4,5].map(n=>`<button data-count="${n}" class="${state.count===n?'selected':''}" aria-pressed="${state.count===n}">${n}</button>`).join('')}</div><button class="text-button" data-action="demo">Try with a sample PFP →</button><label class="label" for="trigger">When should your puzzle run?</label><select class="search" style="font-size:11px;margin:0;padding:10px" id="trigger">${[['buy','Someone buys'],['sell','Someone sells'],['fees','Creator fees arrive'],['holders','A holder milestone'],['timer','A timer fires']].map(([id,text])=>`<option value="${id}" ${state.trigger===id?'selected':''}>${text}</option>`).join('')}</select><p class="help">You can test your ideas before launch. Actions run in the local simulator.</p></aside><section class="builder-main"><h2>Piece your coin together.</h2><p class="help">Choose ${state.count} things your coin should do. Each one connects a piece of your PFP.</p><div class="assembly"><span class="board-label">${completed?'THE BIGGER PICTURE, COMPLETE.':'YOUR PFP · ONE PIECE AT A TIME'}</span>${puzzleSVG({count:state.count,image:state.image||demoImage,selected:state.items.length,scatter:true,labels:true})}</div><div class="progress-line"><span>${state.items.length} of ${state.count} pieces connected</span><span>${completed?'✓ Puzzle complete!':state.image?'Find your next piece ↓':'Upload your PFP to begin'}</span></div><div class="progress-bar"><div style="width:${state.items.length/state.count*100}%"></div></div><div class="behavior-list">${behaviors.map(b=>{const i=state.items.findIndex(i=>i.id===b.id);return `<button class="behavior ${i>=0?'selected':''}" style="--card:${b.color}" data-behavior="${b.id}" aria-pressed="${i>=0}" ${!state.image?'disabled':''}><span class="code">${b.code} · ${b.category.toUpperCase()}</span><span class="check">${i>=0?'✓':''}</span><strong>${b.name}</strong><small>${b.desc}</small>${i>=0?`<span style="font-size:9px;display:block;margin-top:5px">Piece ${i+1} connected</span>`:''}</button>`;}).join('')}</div><div class="builder-bottom"><small>${completed?'All connected. Let’s make it yours.':'Connect every piece to continue.'}</small><button class="button yellow" data-action="next" ${completed?'':'disabled'}>Next: coin details <span>→</span></button></div></section><aside class="build-preview"><div><h3>The bigger picture</h3><p class="help">Your PFP, your personality.</p>${puzzleSVG({count:state.count,image:state.image||demoImage,selected:state.items.length})}<div class="status">${completed?'● ALL PIECES CONNECTED':`○ ${state.count-state.items.length} PIECES TO GO`}</div></div><div><div class="selected-list">${state.items.length?state.items.map((item,i)=>{const b=behaviors.find(b=>b.id===item.id);return `<div class="selected-row"><span class="ordinal">${i+1}</span><span>${b.name}</span><button class="text-button" data-configure="${item.id}" aria-label="Configure ${b.name}" style="margin-left:auto">Edit</button></div>`;}).join(''):'<p class="help">Your selected pieces will appear here. Start with something your community will love.</p>'}</div><button class="button full" data-action="simulate" ${state.items.length?'':'disabled'} style="font-size:11px;gap:10px">▷ Test your puzzle</button><button class="text-button" data-action="reset">Start a fresh puzzle</button></div></aside></div></main>`;}
function details(){return `<main>${builderTop()}<div class="details-layout"><form id="details-form" class="form-panel"><h2>Give your puzzle a name.</h2><div class="form-row"><label class="field">Coin name<input name="name" maxlength="32" required placeholder="The Missing Piece" value="${escape(state.name)}"></label><label class="field">Ticker<input name="symbol" maxlength="13" pattern="[A-Za-z0-9_]+" required placeholder="PIECE" value="${escape(state.symbol)}"></label></div><label class="field">Description<textarea name="description" maxlength="1000" placeholder="Tell the world what you’re piecing together…">${escape(state.description)}</textarea></label><label class="field">Website <span style="font-weight:400">(optional)</span><input type="url" name="website" placeholder="https://your-site.com" value="${escape(state.website)}"></label><div class="form-row"><label class="field">X / Twitter <span style="font-weight:400">(optional)</span><input type="url" name="twitter" placeholder="https://x.com/yourcoin" value="${escape(state.twitter)}"></label><label class="field">Telegram <span style="font-weight:400">(optional)</span><input type="url" name="telegram" placeholder="https://t.me/yourcoin" value="${escape(state.telegram)}"></label></div><div class="builder-bottom"><button type="button" class="text-button" data-action="back">← Back to pieces</button><button class="button yellow" type="submit">Review your coin →</button></div></form><aside><div class="coin-preview">${puzzleSVG({count:state.count,image:state.image,all:true})}<h3 id="preview-name">${escape(state.name||'Your next big idea')}</h3><span id="preview-symbol" class="small-tag">$${escape(state.symbol||'YOURCOIN')}</span><p id="preview-description">${escape(state.description||`${state.count} pieces. One complete picture.`)}</p></div><div class="inline-note">Your PFP is complete. Your ${state.count} selected behaviors stay attached to your saved puzzle project.</div><button class="text-button" data-action="download-image">Download your PFP ↓</button></aside></div></main>`;}
function review(){return `<main>${builderTop()}<div class="details-layout"><section class="form-panel"><h2>The final piece: your launch.</h2><div class="inline-note success-note">✓ ${state.count} pieces connected · PFP complete · Coin details ready</div><h3 style="font-size:15px">Launch on pump.fun</h3><p class="help">Connect your Solana wallet to create your coin. Your wallet will show the transaction and network costs before you sign.</p><button class="button yellow full" data-action="wallet">${wallet?'✓ '+escape(wallet.publicKey.toBase58().slice(0,5)+'…'+wallet.publicKey.toBase58().slice(-5)):'Connect a Solana wallet'} <span>↗</span></button><label class="field" style="margin-top:25px">Public token metadata URI<input id="metadata-uri" type="url" maxlength="200" value="${escape(state.metadataURI)}" placeholder="https://…/metadata.json or ipfs://…"><small>Your metadata must publicly host this coin’s name, ticker, description, and completed PFP. Download the launch files below to publish them on IPFS.</small></label><details><summary class="help" style="cursor:pointer;font-weight:700">RPC connection & metadata tools</summary><label class="field" style="margin-top:18px">Solana mainnet RPC URL<input id="rpc-url" type="url" value="${escape(state.rpc)}" placeholder="https://your-mainnet-rpc"><small>Use a mainnet RPC that permits browser requests. Public endpoints may rate-limit transactions.</small></label><label class="field">Public PFP image URI<input id="image-uri" value="${escape(state.imageURI)}" placeholder="ipfs://… or https://…/pfp.png"><small>Host your downloaded PFP, paste its URI, then download metadata.json.</small></label><div class="page-actions" style="flex-wrap:wrap"><button class="chip" data-action="download-image">Download PFP</button><button class="chip" data-action="download-metadata">Download metadata.json</button><button class="chip" data-action="export">Export puzzle rules</button></div></details><div class="inline-note">Your selected behaviors can be tested in PUZZLED’s simulator. Launching creates a pump.fun token; autonomous buybacks, AI, payouts, and social actions require a separate live execution service.</div><label class="help" style="display:flex;gap:10px;margin:20px 0;align-items:start"><input id="launch-ack" type="checkbox">I’ve checked my metadata and understand that creating a coin costs SOL and its on-chain details cannot be edited.</label><button class="button yellow full" data-action="launch" ${launchBusy||submitted?'disabled':''}>${submitted?'Transaction submitted':launchBusy?'Creating your coin…':'Create coin on pump.fun'} <span>↗</span></button><div id="launch-status" class="launch-status" aria-live="polite"></div><div class="builder-bottom"><button class="text-button" data-action="back">← Edit coin details</button><a class="plain-link" href="https://pump.fun/create" target="_blank" rel="noopener">Use pump.fun’s own form ↗</a></div></section><aside><div class="coin-preview">${puzzleSVG({count:state.count,image:state.image,all:true})}<h3>${escape(state.name)}</h3><span class="small-tag">$${escape(state.symbol)}</span><p>${escape(state.description)}</p></div><div class="selected-list">${state.items.map((i,n)=>`<div class="selected-row"><span class="ordinal">${n+1}</span>${behaviors.find(b=>b.id===i.id).name}</div>`).join('')}</div><button class="button full" data-action="simulate">▷ Run one final test</button><button class="text-button" data-action="export">Download your complete project ↓</button></aside></div></main>`;}
function library(){return `<main><div class="page-intro"><span class="small-tag">THE PIECE LIBRARY</span><h1>Anything can be a piece.</h1><p>Events, logic, characters, media, and money. Browse the building blocks for your next big picture.</p></div><div class="page-body"><input class="search" id="module-search" aria-label="Search pieces" placeholder="Search pieces, categories, or ideas…"><div class="modules-grid" id="module-results">${moduleCards()}</div><div class="inline-note" style="margin-top:45px">Available behaviors are simulated in the builder. Coin creation uses the official pump.fun SDK. Live autonomous behaviors require an execution service.</div></div></main>${footer()}`;}
function examples(gallery=false){return `<main><div class="page-intro"><span class="small-tag">${gallery?'THE PUZZLE GALLERY':'A LITTLE INSPIRATION'}</span><h1>${gallery?'Every picture starts somewhere.':'Good ideas fit together.'}</h1><p>Start from a 3, 4, or 5-piece example. Upload your own PFP, adjust every behavior, and make the puzzle yours.</p></div><div class="page-body"><div class="filter-row"><button class="chip active" data-filter="all">All puzzles</button>${[3,4,5].map(n=>`<button class="chip" data-filter="${n}">${n} pieces</button>`).join('')}</div><div class="examples-grid" id="example-results">${exampleCards()}</div></div></main>${footer()}`;}
function explore(){const launched=drafts.filter(d=>d.mint);return `<main><div class="page-intro"><span class="small-tag">EXPLORE PUZZLED</span><h1>See the bigger picture.</h1><p>Coins created from this device appear here after a confirmed launch. Explore examples while you build your first puzzle.</p></div><div class="page-body">${launched.length?`<div class="examples-grid">${launched.map(coinCard).join('')}</div>`:`<div class="empty-state"><img src="mascot.svg" alt="Pip"><h2>The first piece could be yours.</h2><p class="help">No confirmed coin launches on this device yet.</p><a class="button yellow" href="#/build">Build your first coin →</a></div>`}<div class="section-head" style="margin-top:55px"><h2 style="font-size:25px">Puzzles to get you started</h2><span class="small-tag">EXAMPLES</span></div><div class="examples-grid">${exampleCards()}</div></div></main>${footer()}`;}
function coinCard(d){return `<article class="piece-card"><div class="example-art" style="--card:#f8f5e7">${puzzleSVG({count:d.count,image:d.image,selected:d.items.length})}</div><h3>${escape(d.name||'Untitled puzzle')}</h3><p>$${escape(d.symbol||'YOURCOIN')} · ${d.items.length}/${d.count} pieces</p><small class="help">${d.mint?'Confirmed on Solana':'Draft saved on this device'}</small><div class="page-actions">${d.mint?`<a class="plain-link" href="https://pump.fun/coin/${d.mint}" target="_blank" rel="noopener">View on pump.fun ↗</a>`:`<button class="chip" data-resume="${d.id}">Continue building →</button>`}</div></article>`;}
function coins(){return `<main><div class="page-intro"><span class="small-tag">YOUR WORKSPACE</span><h1>Your pieces. Your coins.</h1><p>Pick up where you left off. Drafts are saved in this browser. Export a project to keep it with you.</p></div><div class="page-body"><div class="page-actions"><button class="button yellow" data-action="new">New puzzle +</button><button class="button" data-action="import">Import project ↑</button><input id="import-input" type="file" accept="application/json" hidden></div>${drafts.length?`<div class="examples-grid">${drafts.map(coinCard).join('')}</div>`:`<div class="empty-state"><img src="mascot.svg" alt="Pip"><h2>A clean slate. A fresh puzzle.</h2><p class="help">Start building and your project will be saved here.</p></div>`}</div></main>${footer()}`;}
function pair(){return `<main><div class="page-intro"><span class="small-tag">A NEW CONNECTION</span><h1>Pair your ideas.</h1><p>Build a puzzle around your community’s favorite stock. These are builder themes; live tokenized-stock buying needs an execution integration.</p></div><div class="page-body"><div class="modules-grid">${[['NVDA','NVIDIA',colors[1]],['TSLA','Tesla',colors[3]],['AAPL','Apple',colors[4]],['SPY','S&P 500',colors[0]]].map(([s,n,c])=>`<article class="piece-card" style="--card:${c}"><span class="category-icon">SK</span><h3>${s}</h3><p>${n}</p><button class="text-button" data-pair="${s}">Start a themed puzzle →</button></article>`).join('')}</div><div class="inline-note" style="margin-top:45px">Pairing a theme does not buy stocks or change a token’s price. PUZZLED’s simulator helps you explore an idea before connecting a live service.</div></div></main>${footer()}`;}
const docsSections=[['start','How the pieces fit',`Upload a PNG, JPG, or WebP PFP and choose 3, 4, or 5 pieces. Every selected behavior brings one piece into place. Fill every slot to unlock coin details. Click a selected behavior to remove it, or use Edit to configure it.`],['pieces','Give every piece a purpose',`Choose behaviors from the library. An event starts your puzzle and the pieces run in the order you selected them. Conditions gate the following pieces. Replacing the image or changing the piece count starts a new assembly. The original uploaded picture is center-cropped to 1000 × 1000 pixels.`],['simulation','Test your puzzle',`The simulator runs on this device with pretend events, tokens, and SOL. It follows your selected sequence and configuration. Counters persist locally. External calls, AI-generated media, money transfers, and social posts are represented by simulated output; they do not execute on external services.`],['launch','Launching on pump.fun',`Complete your puzzle, enter your coin details, and connect a Solana wallet. Publish your PFP and metadata JSON on a public host such as IPFS. Paste the metadata URI and use a browser-compatible mainnet RPC. PUZZLED uses the official @pump-fun/pump-sdk create_v2 instruction to build a token-creation transaction. The wallet signs it and Solana confirms it. Rent and network fees are paid in SOL. The metadata URI and coin details are permanent on-chain.`],['execution','Live behavior execution',`Coin creation and behavior execution are separate. Your exported puzzle is a structured rule plan. Autonomous buybacks, burns, holder rewards, AI generation, APIs, social posts, and bounties need a production event listener, authenticated execution service, funding policy, and integration credentials. This version saves and simulates those rules; it does not deploy that service or lock rules on Solana.`],['metadata','Your public metadata',`Download the PFP and publish it on IPFS or another public image host. Add that URI in the review step and download metadata.json. Publish the JSON and paste its public URI into the launch form. It includes the name, symbol, description, public PFP URI, optional social links, and a PUZZLED rule-plan extension. Private Sites URLs and local file paths cannot be used by public coin explorers.`],['faq','Questions and answers',`Can I use my own PFP? Yes. Can I select more than 5 pieces? This builder supports exactly 3, 4, or 5. Can I change a draft? Yes. Can I undo a completed piece? Click the behavior to remove it. Where are my coins saved? In this browser, with a project export for portability. Will my behaviors automatically run after launch? They require a separate live execution service; see the section above.`],['privacy','Your data',`Your image, project drafts, and simulations are stored locally in this browser. Uploaded PFPs are not sent to PUZZLED servers. Connecting a wallet shares its public address with this page. On launch, your signed transaction is sent to the selected Solana RPC, and the public metadata is referenced on-chain. Wallet private keys are never requested or exported.`]];
function docs(){return `<main><div class="page-intro"><span class="small-tag">THE INSTRUCTIONS, PIECED TOGETHER</span><h1>How PUZZLED works.</h1><p>From a broken picture to a complete idea. Everything you need to know before the final piece.</p></div><div class="page-body doc-layout"><nav class="doc-nav" aria-label="Documentation">${docsSections.map(([id,title])=>`<a href="#/docs?section=${id}">${title}</a>`).join('')}</nav><div class="doc-content">${docsSections.map(([id,title,text])=>`<section id="doc-${id}"><h2>${title}</h2><p>${text}</p>${id==='launch'?'<a class="plain-link" href="https://github.com/pump-fun/pump-public-docs/blob/main/docs/instructions/COIN_CREATION.md" target="_blank" rel="noopener">Official pump.fun coin creation docs ↗</a>':''}</section>`).join('')}</div></div></main>${footer()}`;}
function render(){const [raw,query='']=(location.hash||'#/').slice(1).split('?');const path=raw||'/';document.querySelectorAll('header nav a').forEach(a=>a.classList.toggle('active',a.hash.split('?')[0]==='#'+path));$('header nav').classList.remove('open');const views={'/':home,'/describe':home,'/build':builder,'/modules':library,'/examples':examples,'/gallery':()=>examples(true),'/explore':explore,'/coins':coins,'/pair':pair,'/docs':docs};app.innerHTML=(views[path]||home)();document.title=`PUZZLED · ${path==='/build'?'Your puzzle workspace':path==='/modules'?'The piece library':path==='/docs'?'How it works':'Every piece has a purpose'}`;bind();if(path==='/describe')$('#describe')?.scrollIntoView();if(path==='/docs'&&new URLSearchParams(query).get('section'))$('#doc-'+new URLSearchParams(query).get('section'))?.scrollIntoView();}
function route(path){if(location.hash==='#'+path)render();else location.hash='#'+path;}
function startTemplate(id){const t=templates.find(t=>t.id===id);state={...blank(),count:t.count,image:demoImage,isDemo:true,name:t.name,symbol:t.ticker,description:t.desc,items:t.items.map(id=>({id,value:behaviors.find(b=>b.id===id).value}))};step=1;save();route('/build');toast('Example loaded. Swap in your own PFP or edit any piece.');}
function fromIdea(idea){const lower=idea.toLowerCase(),ids=[];for(const [word,id] of [['condition','condition'],['buy back','buyback'],['buyback','buyback'],['burn','burn'],['reward','airdrop'],['airdrop','airdrop'],['character','agent'],['agent','agent'],['meme','meme'],['post','post'],['feed','post'],['bounty','bounty'],['webhook','webhook'],['counter','counter']])if(lower.includes(word)&&!ids.includes(id))ids.push(id);if(ids.length<3)for(const id of ['counter','post','airdrop'])if(!ids.includes(id)&&ids.length<3)ids.push(id);state={...blank(),count:Math.min(5,Math.max(3,ids.length)),image:demoImage,isDemo:true,description:idea,trigger:lower.includes('fees')?'fees':lower.includes('sell')?'sell':lower.includes('timer')?'timer':'buy',items:ids.slice(0,5).map(id=>({id,value:behaviors.find(b=>b.id===id).value}))};step=1;save();route('/build');toast('Starting puzzle found from your keywords. Edit each piece to make it yours.');}
function configure(id){const b=behaviors.find(b=>b.id===id),item=state.items.find(i=>i.id===id);dialog(`<h2>${b.name}</h2><p>Give this piece its instructions. You can try them in the simulator.</p><form id="config-form"><label class="field">${b.param}<input name="value" value="${escape(item.value)}" ${['buyback','burn','airdrop','condition'].includes(id)?'type="number" min="0.000001" step="any" required':id==='webhook'?'type="url" required':'required maxlength="240"'}></label><div class="dialog-actions"><button class="chip" type="button" data-close>Cancel</button><button class="button yellow" type="submit">Save piece ✓</button></div></form>`);$('#config-form').onsubmit=e=>{e.preventDefault();const value=new FormData(e.target).get('value');if(id==='webhook'&&!value.startsWith('https://'))return toast('Use an HTTPS webhook URL.');item.value=value;save();closeDialog();render();};$('[data-close]').onclick=closeDialog;}
function simulate(){let log=`LOCAL SIMULATION · ${state.trigger.toUpperCase()} EVENT\nPretend amount: 1 SOL · pretend holders: 100\n\n`,allowed=true;state.items.forEach((i,n)=>{const b=behaviors.find(b=>b.id===i.id);if(!allowed){log+=`${n+1}. SKIPPED · ${b.name}\n`;return;}switch(i.id){case'condition':allowed=1>=Number(i.value);log+=`${n+1}. CHECK · 1 SOL ≥ ${i.value} SOL → ${allowed?'PASS':'STOP'}\n`;break;case'counter':state.counter=(Number(state.counter)||0)+1;log+=`${n+1}. STATE · ${i.value} = ${state.counter}\n`;break;case'buyback':log+=`${n+1}. SIMULATED · Buy back with ${i.value} SOL\n`;break;case'burn':log+=`${n+1}. SIMULATED · Burn ${i.value} tokens\n`;break;case'airdrop':log+=`${n+1}. SIMULATED · Distribute ${i.value} SOL among 100 holders\n`;break;case'agent':log+=`${n+1}. SIMULATED · ${i.value} character created: Pip #${Math.floor(Math.random()*1000)}\n`;break;case'post':log+=`${n+1}. SIMULATED POST · ${i.value}\n`;break;case'webhook':log+=`${n+1}. SIMULATED REQUEST · ${i.value||'Configure an HTTPS URL'}\n`;break;case'meme':log+=`${n+1}. SIMULATED MEDIA PROMPT · ${i.value}\n`;break;case'write':log+='SIMULATED AI PROMPT · '+i.value+'\n';break;case'world':log+='SIMULATED WORLD ENTITY · '+i.value+'\n';break;case'random':{const choices=i.value.split(',').map(s=>s.trim()).filter(Boolean);log+='LOCAL RANDOM VALUE · '+choices[Math.floor(Math.random()*choices.length)]+'\n';break;}case'bounty':log+=`${n+1}. SIMULATED BOUNTY · ${i.value}\n`;break;}});save();dialog(`<h2>Your puzzle, in motion.</h2><p>This test uses pretend events and funds. Counters update only on this device.</p><div class="sim-log">${escape(log)}</div><div class="dialog-actions"><button class="button yellow" data-close>Looks good ✓</button></div>`);$('[data-close]').onclick=closeDialog;}
async function readImage(file){if(!file||!['image/png','image/jpeg','image/webp'].includes(file.type))return toast('Choose a PNG, JPG, or WebP image.');if(file.size>15*1024*1024)return toast('Your image must be smaller than 15 MB.');const url=URL.createObjectURL(file);try{const img=new Image();img.src=url;await img.decode();const canvas=document.createElement('canvas');canvas.width=canvas.height=1000;const context=canvas.getContext('2d');const size=Math.min(img.width,img.height);context.fillStyle='#fff';context.fillRect(0,0,1000,1000);context.drawImage(img,(img.width-size)/2,(img.height-size)/2,size,size,0,0,1000,1000);state.image=canvas.toDataURL('image/jpeg',.86);state.isDemo=false;state.items=[];state.metadataURI='';state.imageURI='';save();render();toast(`PFP split into ${state.count} pieces. Pick your first behavior.`);}catch{toast('That image could not be read. Try another file.');}finally{URL.revokeObjectURL(url);}}
function download(blob,name){const link=document.createElement('a'),url=URL.createObjectURL(blob);link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportProject(){download(new Blob([JSON.stringify({format:'puzzled-project',version:1,project:state},null,2)],{type:'application/json'}),`${state.symbol||'puzzled'}-project.json`);toast('Project exported.');}
async function downloadImage(){const image=new Image();image.src=state.image||demoImage;await image.decode();const canvas=document.createElement('canvas');canvas.width=canvas.height=1000;canvas.getContext('2d').drawImage(image,0,0,1000,1000);canvas.toBlob(blob=>download(blob,`${state.symbol||'puzzled'}-pfp.png`),'image/png');}
function downloadMetadata(){if(!/^(https:\/\/|ipfs:\/\/)/.test(state.imageURI))return toast('Add the public PFP image URI before downloading metadata.');const meta={name:state.name,symbol:state.symbol,description:state.description,image:state.imageURI,showName:true,...Object.fromEntries(['website','twitter','telegram'].filter(k=>state[k]).map(k=>[k,state[k]])),extensions:{puzzled:{version:1,pieceCount:state.count,trigger:state.trigger,behaviors:state.items,execution:'requires-live-execution-service'}}};download(new Blob([JSON.stringify(meta,null,2)],{type:'application/json'}),'metadata.json');}
async function connectWallet(){const providers=[window.phantom?.solana,window.solflare,window.solana].filter(Boolean);const provider=providers.find(p=>typeof p.connect==='function'&&typeof p.signTransaction==='function');if(!provider){dialog('<h2>A wallet is your final piece.</h2><p>Open this site in a browser with Phantom or Solflare installed, or in your wallet’s browser, then connect here.</p><div class="page-actions"><a class="button yellow" href="https://phantom.com" target="_blank" rel="noopener">Get Phantom ↗</a><a class="button" href="https://solflare.com" target="_blank" rel="noopener">Solflare ↗</a></div><button class="text-button" data-close>Close</button>');$('[data-close]').onclick=closeDialog;return;}try{await provider.connect();if(!provider.publicKey)throw new Error('Wallet connection did not return a public key.');wallet=provider;render();toast('Wallet connected.');}catch(e){toast(e.message||'Wallet connection cancelled.');}}
async function createCoin(){if(launchBusy||submitted)return;if(!wallet)return toast('Connect your Solana wallet first.');if(!$('#launch-ack').checked)return toast('Review the launch details and check the confirmation box.');if(!/^(https:\/\/|ipfs:\/\/)/.test(state.metadataURI)||state.metadataURI.length>200)return toast('Enter a public HTTPS or IPFS metadata URI.');if(!/^https:\/\//.test(state.rpc))return toast('Use an HTTPS Solana mainnet RPC endpoint.');const status=$('#launch-status');launchBusy=true;const button=$('[data-action="launch"]');button.disabled=true;button.textContent='Creating your coin…';try{const {launchToken}=await import('./launch.bundle.js');const result=await launchToken({wallet,name:state.name,symbol:state.symbol,uri:state.metadataURI,rpc:state.rpc,onStatus:message=>status.textContent=message});submitted=result;state.mint=result.mint;state.signature=result.signature;save();status.innerHTML=`<div class="inline-note success-note">✓ Your coin is confirmed on Solana.<br><a class="plain-link" href="https://pump.fun/coin/${result.mint}" target="_blank" rel="noopener">View on pump.fun ↗</a><br><a class="text-button" href="https://solscan.io/tx/${result.signature}" target="_blank" rel="noopener">View transaction ↗</a></div>`;button.textContent='Coin created ✓';}catch(e){if(e.signature){submitted={signature:e.signature,mint:e.mint};state.pendingLaunch=submitted;save();status.innerHTML=`<div class="inline-note warning-note">Transaction submitted; confirmation is uncertain. Check the transaction before trying again.<br><a href="https://solscan.io/tx/${e.signature}" target="_blank" rel="noopener">Check transaction ↗</a></div>`;button.textContent='Check submitted transaction';}else{status.textContent=e.message||'Launch failed. Check your wallet and RPC.';button.disabled=false;button.textContent='Create coin on pump.fun ↗';}}finally{launchBusy=false;}}
async function importProject(file){try{if(file.size>5*1024*1024)throw new Error('Project file is too large.');const input=JSON.parse(await file.text()),p=input.project;if(input.format!=='puzzled-project'||![3,4,5].includes(p?.count)||!Array.isArray(p.items)||p.items.length>p.count||!p.items.every(i=>behaviors.some(b=>b.id===i.id)&&typeof i.value==='string')||new Set(p.items.map(i=>i.id)).size!==p.items.length)throw new Error('This is not a valid PUZZLED project.');if(p.image&&!/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(p.image)&&p.image!==demoImage)throw new Error('The project image is not supported.');state={...blank(),...p,id:crypto.randomUUID(),mint:undefined,signature:undefined,pendingLaunch:undefined};step=1;submitted=null;save();route('/build');toast('Puzzle imported.');}catch(e){toast(e.message||'Could not import that project.');}}
function newPuzzle(){state=blank();step=1;submitted=null;save();route('/build');}
function bind(){if($("#launch-status")){import("./launch.bundle.js").then(()=>{$("#launch-status").textContent=submitted?"This project already has a submitted transaction. Check My coins or the explorer before creating another.":"Wallet launch code ready.";}).catch(()=>{$("#launch-status").textContent="The wallet launch code could not load. Refresh the page before creating a coin.";});}document.querySelectorAll('[data-template]').forEach(el=>el.onclick=()=>startTemplate(el.dataset.template));document.querySelectorAll('[data-idea]').forEach(el=>el.onclick=()=>{$('#idea-form textarea').value=el.dataset.idea;$('#idea-form textarea').focus();});$('#idea-form')?.addEventListener('submit',e=>{e.preventDefault();const idea=$('#idea-form textarea').value.trim();if(idea.length<5)return toast('Add a few words about your coin idea.');fromIdea(idea);});document.querySelectorAll('[data-count]').forEach(el=>el.onclick=()=>{const count=Number(el.dataset.count);if(count===state.count)return;state.count=count;state.items=[];save();render();toast(`Your PFP now has ${count} pieces. Select ${count} behaviors.`);});document.querySelectorAll('[data-behavior]').forEach(el=>el.onclick=()=>{const id=el.dataset.behavior,at=state.items.findIndex(i=>i.id===id);if(at>=0)state.items.splice(at,1);else if(state.items.length<state.count)state.items.push({id,value:behaviors.find(b=>b.id===id).value});else return toast(`All ${state.count} pieces are connected. Remove a behavior to choose another.`);save();render();if(state.items.length===state.count)toast('Every piece fits! Your PFP is complete.');});document.querySelectorAll('[data-configure]').forEach(el=>el.onclick=()=>configure(el.dataset.configure));document.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>{switch(el.dataset.action){case'upload':$('#file-input').click();break;case'demo':state.image=demoImage;state.isDemo=true;state.items=[];save();render();break;case'next':if(state.image&&state.items.length===state.count){step=2;save();render();window.scrollTo(0,0);}break;case'back':step=Math.max(1,step-1);render();break;case'simulate':simulate();break;case'reset':case'new':newPuzzle();break;case'export':exportProject();break;case'import':$('#import-input').click();break;case'download-image':downloadImage();break;case'download-metadata':downloadMetadata();break;case'wallet':connectWallet();break;case'launch':createCoin();break;}});$('#file-input')?.addEventListener('change',e=>readImage(e.target.files[0]));const upload=$('.upload-zone');upload?.addEventListener('dragover',e=>{e.preventDefault();upload.style.background='#fff0c6';});upload?.addEventListener('dragleave',()=>upload.style.background='');upload?.addEventListener('drop',e=>{e.preventDefault();readImage(e.dataTransfer.files[0]);});$('#trigger')?.addEventListener('change',e=>{state.trigger=e.target.value;save();});$('#details-form')?.addEventListener('submit',e=>{e.preventDefault();const fields=new FormData(e.target);for(const k of ['name','symbol','description','website','twitter','telegram'])state[k]=fields.get(k).trim();state.symbol=state.symbol.toUpperCase();if(new TextEncoder().encode(state.name).length>32||new TextEncoder().encode(state.symbol).length>13)return toast('Name must fit 32 bytes; ticker must fit 13 bytes. Shorten these fields.');save();step=3;render();window.scrollTo(0,0);});$('#details-form')?.addEventListener('input',e=>{const names={name:'#preview-name',symbol:'#preview-symbol',description:'#preview-description'};if(names[e.target.name])$(names[e.target.name]).textContent=(e.target.name==='symbol'?'$':'')+e.target.value;});[['metadata-uri','metadataURI'],['rpc-url','rpc'],['image-uri','imageURI']].forEach(([id,key])=>$('#'+id)?.addEventListener('input',e=>{state[key]=e.target.value.trim();save();}));$('#module-search')?.addEventListener('input',e=>{const q=e.target.value.toLowerCase();$('#module-results').innerHTML=moduleCards(modules.filter(m=>m.join(' ').toLowerCase().includes(q)))||'<p>No pieces found. Try another search.</p>';});document.querySelectorAll('[data-filter]').forEach(el=>el.onclick=()=>{document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b===el));$('#example-results').innerHTML=exampleCards(el.dataset.filter==='all'?templates:templates.filter(t=>t.count===Number(el.dataset.filter)));document.querySelectorAll('[data-template]').forEach(b=>b.onclick=()=>startTemplate(b.dataset.template));});document.querySelectorAll('[data-resume]').forEach(el=>el.onclick=()=>{state={...blank(),...drafts.find(d=>d.id===el.dataset.resume)};step=1;submitted=state.pendingLaunch||null;save();route('/build');});document.querySelectorAll('[data-pair]').forEach(el=>el.onclick=()=>{state={...blank(),image:demoImage,isDemo:true,count:3,name:`${el.dataset.pair} Puzzle`,symbol:`P${el.dataset.pair}`,description:`A community puzzle inspired by ${el.dataset.pair}.`,items:['counter','post','buyback'].map(id=>({id,value:behaviors.find(b=>b.id===id).value}))};step=1;save();route('/build');});$('#import-input')?.addEventListener('change',e=>{if(e.target.files[0])importProject(e.target.files[0]);});}
